 dict(q="Il permesso per attesa occupazione si può rinnovare?", a="Alla scadenza si rinnova solo con un nuovo rapporto di lavoro o con un reddito calcolato secondo l'art. 29 c.3 lett. b: almeno l'assegno sociale per il solo titolare, maggiorato della metà per ogni familiare a carico.", norme=["art. 22 c.11 TU 286/1998"], tag=["attesa occupazione", "rinnovo"]),
